import pytest
from candidate import smallest_change

class TestSmallestChange:
    def test_normal_case_all_mismatched(self):
        assert smallest_change([1, 2, 3, 5, 4, 7, 9, 6]) == 4

    def test_normal_case_one_mismatch(self):
        assert smallest_change([1, 2, 3, 4, 3, 2, 2]) == 1

    def test_normal_case_already_palindrome(self):
        assert smallest_change([1, 2, 3, 2, 1]) == 0

    def test_empty_array(self):
        assert smallest_change([]) == 0

    def test_single_element(self):
        assert smallest_change([1]) == 0

    def test_two_elements_same(self):
        assert smallest_change([5, 5]) == 0

    def test_two_elements_different(self):
        assert smallest_change([1, 2]) == 1

    def test_all_same_elements(self):
        assert smallest_change([7, 7, 7, 7, 7]) == 0

    def test_all_different_even_length(self):
        assert smallest_change([1, 2, 3, 4]) == 2

    def test_all_different_odd_length(self):
        assert smallest_change([1, 2, 3, 4, 5]) == 2

    def test_negative_numbers_palindrome(self):
        assert smallest_change([-1, -2, -3, -2, -1]) == 0

    def test_negative_numbers_mismatch(self):
        assert smallest_change([-1, -2, -3, -4, -5]) == 2

    def test_mixed_positive_negative(self):
        assert smallest_change([1, -1, 2, -2, 3]) == 2

    def test_zeros_palindrome(self):
        assert smallest_change([0, 0, 0]) == 0

    def test_zeros_mixed(self):
        assert smallest_change([0, 1, 2]) == 1

    def test_large_values(self):
        assert smallest_change([1000000, 2000000, 1000000]) == 0

    def test_large_values_mismatch(self):
        assert smallest_change([1000000, 2000000, 3000000]) == 1

    def test_symmetric_with_single_mismatch(self):
        assert smallest_change([1, 2, 3, 4, 3, 2, 5]) == 1

    def test_even_length_half_mismatched(self):
        assert smallest_change([1, 2, 3, 4, 1, 2]) == 2

    def test_even_length_all_match(self):
        assert smallest_change([1, 2, 2, 1]) == 0

    def test_three_elements_palindrome(self):
        assert smallest_change([1, 2, 1]) == 0

    def test_three_elements_mismatch(self):
        assert smallest_change([1, 2, 3]) == 1

    def test_six_elements_all_mismatch(self):
        assert smallest_change([1, 2, 3, 4, 5, 6]) == 3

    def test_six_elements_all_match(self):
        assert smallest_change([1, 2, 3, 3, 2, 1]) == 0

    def test_single_zero(self):
        assert smallest_change([0]) == 0

    def test_single_negative(self):
        assert smallest_change([-42]) == 0

    def test_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            smallest_change(None)

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            smallest_change(5)

    def test_tuple_input_works(self):
        assert smallest_change((1, 2, 1)) == 0

    def test_tuple_input_mismatch(self):
        assert smallest_change((1, 2, 3)) == 1

    def test_mixed_types_in_list(self):
        assert smallest_change([1, "a", 1]) == 0

    def test_floats_in_array(self):
        assert smallest_change([1.5, 2.5, 1.5]) == 0

    def test_floats_mismatch(self):
        assert smallest_change([1.5, 2.5, 3.5]) == 1

    def test_very_long_palindrome(self):
        arr = list(range(1, 101)) + list(range(1, 101))
        assert smallest_change(arr) == 0

    def test_very_long_mismatch(self):
        arr = list(range(1, 101)) + list(range(201, 301))
        assert smallest_change(arr) == 100

    def test_input_not_mutated(self):
        arr = [1, 2, 3, 4]
        original = arr[:]
        smallest_change(arr)
        assert arr == original

    def test_boolean_values(self):
        assert smallest_change([True, False, True]) == 0

    def test_boolean_mismatch(self):
        assert smallest_change([True, False, False]) == 1
